const $ = (selector) => document.querySelector(selector);
const sample = { name: 'Rocky the Dragon', type: 'A brave little dragon with a big imagination.', speech: 'Hi! I’m Rocky the Dragon!' };
let current = { ...sample }; let drawingDataUrl = ''; let fileName = ''; let source = ''; let cameraStream = null; let recognition;
const screens = ['welcome-screen', 'source-screen', 'creation-screen', 'alive-screen'];
const progress = [['WELCOME', '01 / 05', 8], ['SHOW YOUR DRAWING', '02 / 05', 28], ['BRING IT TO LIFE', '03 / 05', 58], ['MEET YOUR CREATION', '05 / 05', 100]];
function showScreen(id, progressIndex) { screens.forEach(screen => $(`#${screen}`).classList.toggle('active', screen === id)); const [label, count, width] = progress[progressIndex]; $('#progress-label').textContent = label; $('#progress-count').textContent = count; $('#progress-bar').style.width = `${width}%`; window.scrollTo({ top: 0, behavior: 'smooth' }); }
async function postJSON(path, body) { const response = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }); if (!response.ok) throw new Error('Request failed'); return response.json(); }
function clearSource() { $('#source-preview').hidden = true; $('#pdf-ready').hidden = true; $('#capture-empty').hidden = false; $('#camera-video').hidden = true; $('#source-continue').disabled = true; }
function openSource(type) { source = type; $('#capture-zone').hidden = false; clearSource(); if (type === 'camera') { $('#capture-empty strong').textContent = 'Camera window'; $('#capture-empty small').textContent = 'Press start, then hold your drawing in the frame.'; $('#start-camera').hidden = false; $('#source-status').textContent = 'Start the camera to begin.'; $('#start-camera').focus(); } else { $('#start-camera').hidden = true; $('#capture-empty strong').textContent = 'Choose your drawing'; $('#capture-empty small').textContent = 'Image or PDF files are accepted.'; $('#source-status').textContent = 'Choose an image or PDF from this device.'; $('#file-input').click(); } }
$('#next-button').addEventListener('click', () => showScreen('source-screen', 1));
$('#camera-option').addEventListener('click', () => openSource('camera'));
$('#upload-option').addEventListener('click', () => openSource('upload'));
$('#file-input').addEventListener('change', event => { const file = event.target.files[0]; if (!file) return; fileName = file.name; const reader = new FileReader(); reader.onload = event => { drawingDataUrl = file.type === 'application/pdf' ? '' : event.target.result; if (drawingDataUrl) { $('#source-preview').src = drawingDataUrl; $('#source-preview').hidden = false; $('#capture-empty').hidden = true; } else { $('#capture-empty').hidden = true; $('#pdf-ready').hidden = false; $('#pdf-name').textContent = file.name; } $('#source-continue').disabled = false; $('#source-status').textContent = 'Drawing received. Press continue when you are ready.'; }; reader.readAsDataURL(file); });
async function startCamera() { try { cameraStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }, audio: false }); const video = $('#camera-video'); video.srcObject = cameraStream; video.hidden = false; $('#capture-empty').hidden = true; $('#source-status').textContent = 'Camera is looking. Hold the drawing inside the frame.'; $('#start-camera').textContent = 'CAPTURE DRAWING'; $('#start-camera').onclick = captureCamera; } catch (error) { $('#source-status').textContent = 'Camera permission is needed. You can choose a file instead.'; } }
function stopCamera() { if (cameraStream) cameraStream.getTracks().forEach(track => track.stop()); cameraStream = null; }
function captureCamera() { const video = $('#camera-video'); const canvas = document.createElement('canvas'); canvas.width = video.videoWidth || 1280; canvas.height = video.videoHeight || 720; canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height); drawingDataUrl = canvas.toDataURL('image/jpeg', .92); fileName = 'live-camera-drawing.png'; stopCamera(); video.hidden = true; $('#source-preview').src = drawingDataUrl; $('#source-preview').hidden = false; $('#source-continue').disabled = false; $('#source-status').textContent = 'I can see it! Moving to the magic room…'; setTimeout(beginCreation, 700); }
$('#start-camera').addEventListener('click', startCamera);
$('#source-continue').addEventListener('click', beginCreation);
function beginCreation() { stopCamera(); showScreen('creation-screen', 2); const bar = $('#creation-progress-bar'); const shape = $('#shape-step'); const life = $('#life-step'); bar.style.width = '16%'; setTimeout(() => { bar.style.width = '52%'; shape.classList.add('done'); shape.innerHTML = '✓ <b>Understanding its shape</b>'; $('#creation-title').textContent = 'Finding its personality…'; $('#creation-copy').textContent = 'Tracing the marks, colors, and wonderful story inside your drawing.'; }, 850); setTimeout(() => { bar.style.width = '82%'; life.classList.add('done'); life.innerHTML = '✓ <b>Giving it a voice</b>'; $('#creation-title').textContent = 'Almost ready…'; }, 1750); setTimeout(completeCreation, 2600); }
async function completeCreation() { try { const result = await postJSON('/api/scan', { fileName, source: source || 'upload', drawingDataUrl: drawingDataUrl || undefined }); current = { ...current, ...result.character }; } catch (error) {} if (drawingDataUrl) $('#character-art').src = drawingDataUrl; else $('#character-art').removeAttribute('src'); $('#character-name').textContent = current.name; $('#character-type').textContent = current.type; $('#speech-bubble').textContent = current.speech; try { const storyRes = await postJSON('/api/story', { character: current }); if (storyRes.story && storyRes.story.length) { $('#story-text').textContent = Array.isArray(storyRes.story) ? storyRes.story.join(' ') : storyRes.story; $('#story-box').hidden = false; } } catch (e) { $('#story-box').hidden = true; } showScreen('alive-screen', 3); const art = $('#real-drawing-character'); art.classList.remove('art-arrival'); void art.offsetWidth; art.classList.add('art-arrival'); speak(current.speech); }
function getVoice() { const lang = $('#language-select').value; const voices = window.speechSynthesis?.getVoices?.() || []; const prefix = lang.slice(0, 2).toLowerCase(); return voices.find(voice => voice.lang.toLowerCase().startsWith(prefix)) || voices.find(voice => voice.lang.toLowerCase().startsWith('en')) || voices[0]; }
function speak(text) { $('#speech-bubble').textContent = text; const art = $('#real-drawing-character'); art.classList.add('speaking'); let speakingTimeout = setTimeout(() => art.classList.remove('speaking'), 3500); if (!('speechSynthesis' in window)) return; window.speechSynthesis.cancel(); const styles = { warm: [1.08, .92], bright: [1.38, 1.04], deep: [.78, .86] }; const [pitch, rate] = styles[$('#voice-style').value] || styles.warm; const utterance = new SpeechSynthesisUtterance(text); utterance.lang = $('#language-select').value; utterance.pitch = pitch; utterance.rate = rate; utterance.voice = getVoice(); utterance.onend = () => { clearTimeout(speakingTimeout); art.classList.remove('speaking'); }; utterance.onerror = () => { clearTimeout(speakingTimeout); art.classList.remove('speaking'); }; window.speechSynthesis.speak(utterance); }
function addChat(text, type) { const line = document.createElement('div'); line.className = `chat-line ${type}-line`; line.innerHTML = `<span>${type === 'child' ? '○' : '✦'}</span><p></p>`; line.querySelector('p').textContent = text; $('#chat-log').appendChild(line); $('#chat-log').scrollTop = $('#chat-log').scrollHeight; }
async function sendMessage(message) { if (!message.trim()) return; addChat(message, 'child'); $('#message-input').value = ''; $('#talk-hint').textContent = `${current.name} is thinking…`; try { const result = await postJSON('/api/chat', { message, language: $('#language-select').value, character: current }); addChat(result.reply, 'character'); speak(result.reply); } catch (error) { const fallback = 'That sounds like a wonderful idea. Let’s explore it together!'; addChat(fallback, 'character'); speak(fallback); } $('#talk-hint').textContent = 'Your character is listening.'; }
$('#send-button').addEventListener('click', () => sendMessage($('#message-input').value)); $('#message-input').addEventListener('keydown', event => { if (event.key === 'Enter') sendMessage(event.target.value); });
if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) { const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition; recognition = new Recognition(); recognition.onstart = () => { recognition.lang = $('#language-select').value; $('#talk-button').classList.add('listening'); $('#talk-hint').textContent = 'Listening…'; }; recognition.onresult = event => sendMessage(event.results[0][0].transcript); recognition.onend = () => $('#talk-button').classList.remove('listening'); }
$('#talk-button').addEventListener('click', () => { if (recognition) recognition.start(); else $('#talk-hint').textContent = 'Voice input works best in Chrome or Edge.'; });
$('#speak-button').addEventListener('click', () => speak(current.speech));
$('#language-select').addEventListener('change', () => { if (recognition) recognition.lang = $('#language-select').value; });
$('#restart-button').addEventListener('click', () => { stopCamera(); window.speechSynthesis?.cancel(); drawingDataUrl = ''; fileName = ''; source = ''; $('#story-box').hidden = true; $('#chat-log').innerHTML = '<div class="chat-line character-line"><span>✦</span><p>Ask me anything. I’m here.</p></div>'; $('#message-input').value = ''; showScreen('welcome-screen', 0); });
